#!/usr/bin/env python3
"""Build a portable, dependency-free HTML case study from reviewed data."""
import json,pathlib,html,collections
from research import ROOT,read_json,metrics,decision,write_json
rows=read_json(ROOT/'data/reviewed.json');m=metrics(rows)
cache=[read_json(p) for p in (ROOT/'cache').glob('*.json')]
coverage=collections.Counter(r['status'] for r in cache)
# Only task-relevant, reviewed research fields enter the public-facing HTML.
keys=['id','name','category','description','auth_methods','access_gates','access_summary','api_surface','mcp_status','buildability','blocker','evidence','confidence','checked_at','next_action','routing_reason']
public=[dict({k:r[k] for k in keys},stage=decision(r)) for r in rows]
changes=[]
for r in rows:
 v=r.get('verification',{})
 edits=v if isinstance(v,list) else v.get('changes',[]) if isinstance(v,dict) else []
 for edit in edits:
  if isinstance(edit,dict) and edit.get('field'):
   changes.append({'id':r['id'],'name':r['name'],'field':edit['field'],'before':edit.get('original',''),'after':edit.get('corrected',''),'reason':edit.get('reason','')})
write_json(ROOT/'output/changes.json',changes)
data=json.dumps(public,ensure_ascii=False).replace('</','<\\/')
change_data=json.dumps(changes,ensure_ascii=False).replace('</','<\\/')
audit=read_json(ROOT/'data/audit.json')['summary']
changes.extend(read_json(ROOT/'data/source_refinements.json'))
write_json(ROOT/'output/changes.json',changes)
change_data=json.dumps(changes,ensure_ascii=False).replace('</','<\\/')
